     "**ഒരു എൻട്രിയിൽ ഒരു വരിയിൽ ഇംഗ്ലീഷും മറ്റേ വരിയിൽ ഫ്രഞ്ചും ഉണ്ട് - എന്തുകൊണ്ടാണ് ഇത് പിളരാത്തത്?** ഫോം എ എഴുത്ത് രീതി അനുസരിച്ച് ട്രാക്കുകൾ പിളർത്തുന്നു, അതിനാൽ ഒരൊറ്റ എൻട്രിക്ക് ഉള്ളിൽ ഒരു സിസ്റ്റം പങ്കിടുന്ന രണ്ട് ഭാഷകൾ വേർപെടുത്താൻ കഴിയില്ല. ഇത് ഫോം ബി ആയി പുനഃക്രമീകരിക്കുക (ഒരേ ടൈംലൈനിൽ രണ്ട് എൻട്രികൾ) കൂടാതെ പൊസിഷൻ അടിസ്ഥാനമാക്കിയുള്ള പിളർപ്പ് പ്രവർത്തിക്കുന്നു.",
