   "desc": "സബ്‌ടൈറ്റിലുകളിൽ നിന്ന് സംഭാഷണങ്ങൾ വ്യക്തമായ പ്ലെയിൻ ടെക്സ്റ്റായി വേർതിരിച്ചെടുക്കുക: തുടർച്ചയായ പാരഗ്രാഫുകളായോ അല്ലെങ്കിൽ ഓരോ ക്യൂവിനും ഓരോ വരി എന്ന നിലയിലോ, കൂടാതെ SDH ക്യൂകൾ, വാട്ടർമാർക്കുകൾ, ഡ്യൂപ്ലിക്കേറ്റുകൾ, പ്രിഫിക്സുകൾ, വരികൾ എന്നിവയ്ക്കുള്ള അഞ്ച് സ്വിച്ചുകൾ എന്തൊക്കെയാണ് നീക്കം ചെയ്യുന്നത്.",
