   "intro": "ഒരു സബ്‌ടൈറ്റിൽ ഫയലിൽ നിന്ന് സംഭാഷണം വ്യക്തമായ പ്ലെയിൻ ടെക്സ്റ്റായി പുറത്തെടുക്കുക: ക്യൂ നമ്പറുകൾ, ടൈംലൈനുകൾ, സ്റ്റൈൽ ടാഗുകൾ എന്നിവ സ്വയം നീക്കം ചെയ്യപ്പെടും, അതിനാൽ ഫലം ഒരു ലേഖനം പോലെ വായിക്കാനാകും അല്ലെങ്കിൽ ഒരു ഡയലോഗ് ലിസ്റ്റായി പ്രവർത്തിക്കും.",
   "ctaText": "പ്ലെയിൻ-ടെക്സ്റ്റ് എക്സ്ട്രാക്ടർ തുറക്കുക"
