     "**ഒരു ദ്വിഭാഷാ ഫയൽ രണ്ട് വരികളായോ അതോ ഒരെണ്ണമായോ പുറത്തുവരുന്നത്?** എൻട്രിക്ക് എത്ര വരികൾ ഉണ്ടായിരുന്നോ അത്രയും വരികൾ; ഈ പേജ് അവയെ ലയിപ്പിക്കുകയോ വേർപെടുത്തുകയോ ചെയ്യുന്നില്ല — അവയെ വേർപെടുത്താൻ [[Bilingual split|/bilingual.html]] ഉപയോഗിക്കുക.",
