   "h1": "What 23.976 / 24 / 25 / 30 fps യഥാർത്ഥത്തിൽ എന്താണ് അർത്ഥമാക്കുന്നത്",
   "intro": "23.976 ഉം 24 ഉം തമ്മിലുള്ള 0.1% അന്തരം ടെലിവിഷൻ ചരിത്രത്തിന്റെ ശേഷിപ്പാണ്. PAL-ന്റെ 4%-ഉം ഒപ്പം ചേർന്ന്, സിനിമ പുരോഗമിക്കുമ്പോൾ സബ്‌ടൈറ്റിലുകൾ കൂടുതൽ സമയം തെറ്റിപ്പോകാൻ കാരണം ഇതാണ്.",
