     "ഫലം: NTSC മേഖലകളിൽ സിനിമകൾ 24-ന് പകരം 23.976-ൽ സംപ്രേക്ഷണം ചെയ്യുന്നു. വ്യത്യാസം 0.1% ആണ്, അല്ലെങ്കിൽ ഒരു മണിക്കൂറിൽ 3.6 സെക്കൻഡുകൾ — ഇത് ഒറ്റയ്ക്ക് നോക്കിയാൽ കാര്യമായി ശ്രദ്ധിക്കപ്പെടില്ല, എന്നാൽ താഴെയുള്ള 4%-മായി ഇതിനെ തെറ്റിദ്ധരിക്കരുത്, ഒരിക്കലും ഇവ രണ്ടും ഒരു കണക്കുകൂട്ടലിൽ സംയോജിപ്പിക്കുകയുമരുത്."
