     "**എക്‌സ്‌പോർട്ട് ചെയ്ത ASS-ലെ ശൈലി ഒരു പ്ലെയർ അവഗണിച്ചാലോ?** ശൈലികൾ ഫയലിനുള്ളിലാണ് സംഭരിച്ചിരിക്കുന്നത്, എന്നാൽ ASS-നുള്ള പ്ലെയർ പിന്തുണ വ്യത്യാസപ്പെടാം. കൂടുതൽ പോർട്ടബിളായ രൂപം വേണമെങ്കിൽ, ദ്വിഭാഷാ VTT ശൈലി എക്‌സ്‌പോർട്ട് ചെയ്യുക.",
