     "S :: **കട്ട് പോയിന്റിൽ നിൽക്കുന്ന ഒരു വാചകം വിഭജിക്കപ്പെടുമോ?** ഇല്ല. കട്ടുകൾ എൻട്രി അതിർത്തികളിൽ മാത്രം വീഴുന്നു, കൂടാതെ വര മുറിച്ചുകടക്കുന്ന ഒരു ക്യൂ മുൻ സെഗ്‌മെന്റിൽ തന്നെ തുടരും.",
