     "S :: [[ലളിതമാക്കിയ-പരമ്പരാഗത പരിവർത്തനം|/hanconv.html]] തുറക്കുക, സബ്‌ടൈറ്റിൽ ഡ്രാഗ് ചെയ്യുക, \"പരിവർത്തനം ചെയ്യുക\" എന്നതിന് കീഴിൽ ലളിതമാക്കിയ → പരമ്പരാഗത ദിശകളിലൊന്ന് തിരഞ്ഞെടുക്കുക: ജെനറിക് പരമ്പരാഗത, തായ്‌വാനീസ് (പദാവലി മാറ്റുക), തായ്‌വാനീസ് (ഗ്ലിഫുകൾ മാത്രം) അല്ലെങ്കിൽ ഹോങ്കോംഗ്. പരിവർത്തനം തൽക്ഷണം നടക്കുന്നു, ഫല പ്രദേശം പൂർത്തിയായ സബ്‌ടൈറ്റിൽ കാണിക്കുന്നു, ഡൗൺലോഡ് ചെയ്യാൻ തയ്യാറാണ്.",
     "S :: **തായ്‌വാനീസ് പ്രേക്ഷകർക്ക്**: പ്രദേശിക പദാവലിയും മാറണമെങ്കിൽ \"തായ്‌വാനീസ് (പദാവലി മാറ്റുക)\" തിരഞ്ഞെടുക്കുക — \"സോഫ്റ്റ്‌വെയർ\", \"വിവരങ്ങൾ\" എന്നിവ അവയുടെ തായ്‌വാനീസ് തുല്യങ്ങളായി മാറുന്നു — അല്ലെങ്കിൽ നിങ്ങളുടെ യഥാർത്ഥ പദാവലി സൂക്ഷിച്ചുകൊണ്ട് പ്രതീക രൂപങ്ങൾ മാറണമെങ്കിൽ \"തായ്‌വാനീസ് (ഗ്ലിഫുകൾ മാത്രം)\" തിരഞ്ഞെടുക്കുക. **ഹോങ്കോംഗ് പ്രേക്ഷകർക്ക്**: \"ഹോങ്കോംഗ്\" തിരഞ്ഞെടുക്കുക, അവിടെ \"സോഫ്റ്റ്‌വെയർ\" മറ്റൊരു രൂപത്തിലാണ് എഴുതിയിരിക്കുന്നത്."
