   "h1": "ഒരു വീഡിയോ വേഗത മാറ്റത്തിന് ശേഷം സബ്‌ടൈറ്റിലുകൾ ക്രമീകരിക്കുക",
   "intro": "വീഡിയോ മൊത്തത്തിൽ വേഗതയേറിയതോ മന്ദഗതിയിലുള്ളതോ ആയി മാറി, സബ്‌ടൈറ്റിലുകൾ യഥാർത്ഥ വേഗതയിൽ തുടർന്നു — ഒരു പോയിന്റിന് ശേഷമുള്ളതെല്ലാം തെറ്റാണ്. ഘടകം നൽകുക, മുഴുവൻ ടൈംലൈനും വീഡിയോയ്ക്കൊപ്പം സ്കെയിൽ ചെയ്യുന്നു.",
