   "desc": "AI ഉപയോഗിച്ച് ഉപശീർഷകങ്ങൾ വിവർത്തനം ചെയ്യുക: SRT/VTT/ASS അപ്‌ലോഡ് ചെയ്യുക, 100 ഭാഷകളിൽ നിന്ന് തിരഞ്ഞെടുക്കുക, ഗ്ലോസറി ഉപയോഗിച്ച് പേരുകൾ ഏകീകരിക്കുക, ദ്വിഭാഷാ ഉപശീർഷകങ്ങൾ എക്സ്പോർട്ട് ചെയ്യുക. സൗജന്യമായി ആരംഭിക്കാം, സ്വന്തം API കീ പിന്തുണയ്ക്കുന്നു.",
   "h1": "AI ഉപശീർഷക വിവർത്തനം എങ്ങനെ ഉപയോഗിക്കാം",
   "intro": "ഒരു ഉപശീർഷക ഫയലിനായുള്ള പൂർണ്ണമായ വർക്ക്ഫ്ലോ, അപ്‌ലോഡ് മുതൽ വിവർത്തനം വഴി എക്സ്പോർട്ട് വരെ: സ്ക്രീനിൽ എന്താണുള്ളത്, എന്തിൽ ക്ലിക്ക് ചെയ്യണം, ഓരോ ഘട്ടത്തിലും നിങ്ങൾക്ക് എന്താണ് ലഭിക്കുന്നത്.",
