     "**പേരുകളുടെ വിവർത്തനത്തിൽ സ്ഥിരതയില്ലേ?** സ്ഥിരതയില്ലാത്ത അക്ഷരവിന്യാസങ്ങൾ ഗ്ലോസറിയിൽ ചേർത്ത് വീണ്ടും വിവർത്തനം ചെയ്യുക; ആഗോള \"proper-noun handling\" ക്രമീകരണത്തേക്കാൾ മുൻഗണന ഗ്ലോസറിക്ക് ലഭിക്കും.",
