     "**ഉപശീർഷകങ്ങൾ ചിത്രവുമായി പൊരുത്തപ്പെടുന്നില്ലേ?** ആദ്യം വിവർത്തനം ചെയ്യുക, തുടർന്ന് സമയം ശരിയാക്കുക: വർക്ക്ബെഞ്ചിന്റെ മുകളിലുള്ള ടൈംലൈൻ ടൂൾബാറിന് ഗ്ലോബൽ ഓഫ്സെറ്റും സ്കെയിൽ നിയന്ത്രണവുമുണ്ട് — [[Subtitles drift out of sync toward the end|/guides/subtitles-out-of-sync.html]] കാണുക."
